      "label": "Screen point height y",
      "range": [0, 10, 0.1],
      "default": 4,
      "teaches": "Moving P up or down the screen changes the observation angle θ, and the path difference δl grows or shrinks with it — position on the screen maps directly to path difference"
    },
    {
      "id": "slitSeparation",
      "type": "slider",
      "label": "Slit separation d",
      "range": [0.5, 3, 0.1],
      "default": 1.5,
      "teaches": "Widening the slit gap lengthens δl for the same screen point, making the proportionality δl = d sin θ visible as the extracted segment scales with d"
    },
    {
      "id": "viewMode",
      "type": "toggle",
      "label": "View",
      "options": ["Full apparatus (a)", "Near-slit approximation (b)"],
      "default": "Full apparatus (a)",
      "teaches": "Because D ≫ d, the two long unequal rays become effectively parallel near the slits, and the entire path difference collapses into the single small segment δl of a right triangle"
    }
  ],
  "demo_steps": [
