// short sine wave train drawn along a ray from (x0,y0) toward angle ang (screen coords)
function waveTrain(grp, x0, y0, ang, len) {
  var pts = [], ux = Math.cos(ang), uy = -Math.sin(ang), nx = -uy, ny = ux;
  for (var i = 0; i <= 60; i++) {
