var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
var W = 800, H = 600;
draw.viewbox(0, 0, W, H);

var state = { y: 4, d: 1.5, view: 'a' };
var DSCALE = 60;   // px per unit of d
var YSCALE = 22;   // px per unit of y
var gA = draw.group(), gB = draw.group();

function label(txt, x, y, size, anchor, italic) {
  return draw.text(txt).font({ size: size || 16, family: 'Georgia, serif', style: italic === false ? 'normal' : 'italic' })
    .move(x, y).attr({ 'text-anchor': anchor || 'middle', 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
}
function bracket(x1, y1, x2, y2, grp) {
  grp.line(x1, y1, x2, y2).stroke({ color: '#000', width: 1.4 });
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx*dx+dy*dy), nx = -dy/L*5, ny = dx/L*5;
  grp.line(x1-nx, y1-ny, x1+nx, y1+ny).stroke({ color: '#000', width: 1.4 });
  grp.line(x2-nx, y2-ny, x2+nx, y2+ny).stroke({ color: '#000', width: 1.4 });
}
// arrowhead at (x,y) pointing along direction ang (screen coords, y-down)
function arrowhead(grp, x, y, ang, color, sz) {
  sz = sz || 13;
  var p1 = [x, y];
  var p2 = [x - sz*Math.cos(ang-0.3), y - sz*Math.sin(ang-0.3)];
  var p3 = [x - sz*Math.cos(ang+0.3), y - sz*Math.sin(ang+0.3)];
  grp.polygon([p1, p2, p3].map(function(p){return p.join(',');}).join(' ')).fill(color || '#0e7c8c');
}
// sine wave packet drawn along a ray starting at (x0,y0), direction ang (screen coords), length len
function waveTrain(grp, x0, y0, ang, len) {
  var pts = [], ux = Math.cos(ang), uy = Math.sin(ang), nx = -uy, ny = ux;
  for (var i = 0; i <= 80; i++) {
    var t = i / 80 * len;
    var s = 13 * Math.sin(t / len * Math.PI * 7) * Math.sin(t / len * Math.PI);
    pts.push([x0 + ux*t + nx*s, y0 + uy*t + ny*s]);
  }
  grp.polyline(pts.map(function(p){return p.join(',');}).join(' ')).fill('none')
    .stroke({ color: '#0e7c8c', width: 1.8 });
}
// arc from horizontal (rightward) opening toward angle ang (up = positive ang in world coords)
function thetaArc(grp, x, y, ang, r) {
  var pts = [];
  for (var i = 0; i <= 20; i++) {
    var a = ang * i / 20;
    pts.push([x + r*Math.cos(a), y - r*Math.sin(a)]);
  }
  grp.polyline(pts.map(function(p){return p.join(',');}).join(' ')).fill('none')
    .stroke({ color: '#333', width: 1.2 });
}

function theta() {
  var Dpx = 680, ypx = state.y * YSCALE;
  return Math.atan2(ypx, Dpx);
}

function drawA() {
  gA.clear();
  var bx = 90, sx = 760, midY = 320;
  var dpx = state.d * DSCALE;
  var s1y = midY - dpx/2, s2y = midY + dpx/2;
  var py = midY - state.y * YSCALE;
  var th = theta();
  // barrier & screen
  gA.line(bx, 60, bx, 560).stroke({ color: '#c8a165', width: 8 });
  gA.rect(14, 520).move(sx-7, 60).fill('#b9b9b9').stroke({ color: '#888', width: 1 });
