  gB.line(bx, s1y, bx+ux*rayLen, s1y+uy*rayLen).stroke({ color: '#0e7c8c', width: 2.2 });
  gB.line(bx, s2y, bx+ux*rayLen, s2y+uy*rayLen).stroke({ color: '#0e7c8c', width: 2.2 });
