  gB.line(fx, fy, fx + (fx-bx)*0.35, fy + (fy-s1y)*0.35).stroke({ color: '#555', width: 1.1, dasharray: '5,4' });
  // right-angle square at F
  var nx = -uy, ny = ux;
  var s = 13;
  var p1x = fx + nx*s, p1y = fy + ny*s;
  var p2x = fx - ux*s, p2y = fy - uy*s;
  gB.polyline([p1x, p1y, p1x - ux*s, p1y - uy*s, p2x, p2y].join(',')).fill('none')
    .stroke({ color: '#333', width: 1.3 });
