  }
  gB.polyline(triPts.map(function(p){return p.join(',');}).join(' ')).fill('none')
    .stroke({ color: '#333', width: 1.2 });
  var aMid = (Math.PI/2 - th)/2;
  label('θ', bx + (triR+14)*Math.sin(aMid) - 2, s1y + (triR+14)*Math.cos(aMid) - 8, 16);
  // offset dimension bracket for Δl below the construction (as in the source):
  // dashed extension lines from S2 and F, perpendicular to the ray direction
  var off = 34; // offset distance below the ray
  var ex1x = bx + nx*off,   ex1y = s2y + ny*off;
  var ex2x = fx + nx*off,   ex2y = fy + ny*off;
  gB.line(bx, s2y, bx + nx*(off+8), s2y + ny*(off+8)).stroke({ color: '#555', width: 1.1, dasharray: '5,4' });
  gB.line(fx, fy, fx + nx*(off+8), fy + ny*(off+8)).stroke({ color: '#555', width: 1.1, dasharray: '5,4' });
  // dimension line with arrowheads at both ends
  gB.line(ex1x, ex1y, ex2x, ex2y).stroke({ color: '#000', width: 1.4 });
  arrowhead(gB, ex1x, ex1y, angS + Math.PI, '#000', 10);
  arrowhead(gB, ex2x, ex2y, angS, '#000', 10);
  // Δl label beside the dimension line midpoint, pushed further into open space
  var mlx = (ex1x+ex2x)/2, mly = (ex1y+ex2y)/2;
  label('Δl', mlx + nx*20 - 6, mly + ny*20 - 8, 17);
  // hover
  var hit = gB.rect(W, H).move(0,0).fill('#fff').opacity(0).back();
  hit.on('mousemove', function(e){ showTooltip('δl = d sin θ = ' + (state.d*Math.sin(th)).toFixed(3) + ' — the whole path difference lives in this one segment', e); })
     .on('mouseleave', function(){ hideTooltip(); });
  label('(b)', W/2, 585, 15, 'middle', false);
}

function redraw() {
  if (state.view === 'a') { drawA(); gB.hide(); gA.show(); }
  else { drawB(); gA.hide(); gB.show(); }
}

function update_pointHeight(v) { state.y = v; redraw(); }
